// JPLOGO.EXE - the jelly picture (PSI). Port of JPLOGO/JP.C, JPLOGO/ASM.ASM and
// the line zoomers generated by JPLOGO/DOL.C (ZOOM.INC)
#include "../core/dos.h"
#include "../core/parts.h"
#include "common/readp.h"

extern const int16_t jp_sin1024[1024];

namespace {

using namespace readp_ns;
const int16_t *sin1024 = jp_sin1024;
uint8_t rowdata[400][186];
uint8_t *row[400];
uint8_t palette[768];
uint8_t rowbuf[640 + 256];
int framey1[201], framey2[201];
int framey1t[800], framey2t[800];
int lasty[400], lasts[400];

void scrolly(int y)
{
    int a = y * 80;
    outpw(0x3d4, 0x0d | ((a & 255) << 8));
    outpw(0x3d4, 0x0c | (((a >> 8) & 255) << 8));
}

// ZOOM.INC: one row, source width 185 stretched to width w around x=160
void linezoom(uint16_t dest, const uint8_t *src, int w)
{
    const int BEG = 140, END = 244;
    const int le0 = (160 - END / 2 - 1) & ~7, ri0 = (160 + END / 2 + 8) & ~7;
    if (w > 318) w = 318;
    w &= ~1;
    int y = !w ? 0 : (w < BEG ? BEG : (w > END ? END : w));
    int le = 160 - y / 2, ri = 160 + y / 2, c = ri - le + 1;
    for (int x = le0; x < ri0; x++) {
        uint8_t v = 0;
        if (y && src && x >= le && x <= ri) v = src[((x - le) * 185 + (c / 2)) / c];
        outpw(0x3c4, 0x02 | (0x100 << (x & 3)));
        vga::wr((uint16_t)(dest + (x >> 2)), v);
    }
}

void doit()
{
    int frame = 0, a, b, c, y, xsc, y1 = 0, y2 = 0;
    while (!dis_exit() && dis_musplus() < 4) {}
    while (!dis_exit() && frame < 700) {
        c = dis_waitb();
        frame += c;
        if (frame <= 511) {
            y1 = framey1t[frame] / 16;
            y2 = framey2t[frame] / 16;
        }
        xsc = (400 - (y2 - y1)) / 8;
        for (y = 0; y < 400; y++) {
            if (y < y1 || y >= y2) linezoom((uint16_t)(y * 80), nullptr, 0);
            else {
                b = (int)((int32_t)(y - y1) * 400 / (int32_t)(y2 - y1));
                a = 184 + (sin1024[(b * 32 / 25) & 1023] * xsc + 32) / 64;
                a &= ~1;
                if (lasty[y] != b || lasts[y] != a) {
                    linezoom((uint16_t)(y * 80), row[b], a);
                    lasty[y] = b;
                    lasts[y] = a;
                }
            }
        }
    }
}

} // namespace

void part_jplogo()
{
    const uint8_t *pic = data_file("JP_PIC.BIN");
    if (!pic) return;
    int frame, halt = 0, a = 0, b, c, d, y, la, y1, y2, y1a, y2a, mika;
    dis_partstart();
    memset(rowdata, 0, sizeof rowdata);
    for (a = 0; a < 400; a++) row[a] = rowdata[a];
    a = 0;
    y1 = 0; y1a = 500;
    y2 = 399 * 16; y2a = 500;
    mika = 1;
    for (frame = 0; frame < 200; frame++) {
        if (!halt) {
            y1 += y1a;
            y2 += y2a;
            y2a += 16;
            if (y2 > 400 * 16) {
                y2 -= y2a;
                y2a = -y2a * mika / 8;
                if (mika < 4) mika += 3;
            }
            y1a += 16;
            la = a;
            a = (int16_t)((y2 - y1) - 400 * 16);
            if ((a & 0x8000) ^ (la & 0x8000)) y1a = y1a * 7 / 8;
            y1a += (int16_t)a / 8;
            y2a -= (int16_t)a / 8;
        }
        if (frame > 90) {
            if (y2 >= 399 * 16) {
                y2 = 400 * 16;
                halt = 1;
            } else y2a = 8;
            y1 = y2 - 400 * 16;
        }
        framey1[frame] = y1;
        framey2[frame] = y2;
    }
    framey1[200] = framey2[0];
    framey2[200] = 0;
    for (a = 0; a < 800; a++) {
        b = a / 4; c = a & 3; d = 3 - c;
        framey1t[a] = (framey1[b] * d + framey1[b + 1] * c) / 3;
        framey2t[a] = (framey2[b] * d + framey2[b + 1] * c) / 3;
    }

    vga::setmode(0x13);
    outp(0x3c8, 0);
    for (int i = 0; i < 768; i++) outp(0x3c9, 0);
    outpw(0x3d4, 0x0009);
    outpw(0x3d4, 0x0014);
    outpw(0x3d4, 0xe317);
    outpw(0x3c4, 0x0604);
    outpw(0x3c4, 0x0f02);
    vga::fill(0, 0, 65536);
    outp(0x3c0, 0x11);
    outp(0x3c0, 255);
    outp(0x3c0, 0x20);

    readp(palette, -1, pic);
    palette[64 * 3 + 0] = palette[64 * 3 + 1] = palette[64 * 3 + 2] = 0;
    for (y = 0; y < 400; y++) {
        readp(rowbuf, y, pic);
        memcpy(row[y], rowbuf + 70, 184);
        row[y][184] = 65;
    }
    setpalarea(palette, 0, 256);
    for (a = 0; a < 400; a++)
        for (b = 0; b < 184; b++)
            if (row[a][b] == 0) row[a][b] = 64;

    for (y = 0; y < 400; y++) lasty[y] = lasts[y] = -1;
    dis_waitb();
    scrolly(400);
    dis_waitb();
    for (y = 0; y < 400; y++) linezoom((uint16_t)(y * 80), row[y], 184);
    a = 64; y = 400 * 64;
    while (y > 0) {
        y -= a;
        a += 6;
        if (y < 0) y = 0;
        scrolly(y / 64);
        dis_waitb();
    }
    dis_waitb();
    doit();
}
